exercises.starter:
class Revert(Exception):
    pass

class Chain:
    def __init__(self):
        self.ether = {}

    def send(self, frm, to, amount):
        """Move ether, then run the recipient's code (like an EVM call with value)."""
        if self.ether[frm.name] < amount:
            raise Revert("not enough ether")
        self.ether[frm.name] -= amount
        self.ether[to.name] = self.ether.get(to.name, 0) + amount
        to.receive(frm, amount)

class Account:
    def __init__(self, chain, name, ether=0):
        self.chain, self.name = chain, name
        chain.ether[name] = ether

    def receive(self, frm, amount):
        pass

class Vault(Account):
    def __init__(self, chain):
        super().__init__(chain, "vault")
        self.deposits = {}

    def deposit(self, who, amount):
        self.chain.send(who, self, amount)
        self.deposits[who.name] = self.deposits.get(who.name, 0) + amount

    def withdraw(self, who):
        # Fix this method so that re-entering it cannot take more than `who` deposited.
        amount = self.deposits.get(who.name, 0)
        if amount == 0:
            raise Revert("nothing to withdraw")
        self.chain.send(self, who, amount)
        self.deposits[who.name] = 0

exercises.tests:
class Thief(Account):
    def __init__(self, chain, vault):
        super().__init__(chain, "thief", ether=5)
        self.vault = vault

    def receive(self, frm, amount):
        if frm is self.vault and self.chain.ether["vault"] >= amount:
            try:
                self.vault.withdraw(self)
            except Revert:
                pass

chain = Chain()
vault = Vault(chain)
savers = [Account(chain, n, ether=20) for n in ["Ana", "Bilal", "Chidi", "Dewi"]]
for s in savers:
    vault.deposit(s, 20)
thief = Thief(chain, vault)
vault.deposit(thief, 5)
vault.withdraw(thief)
assert chain.ether["thief"] == 5, f"the thief should end with exactly 5 ether, not {chain.ether['thief']}"
assert chain.ether["vault"] == 80, f"the vault should still hold 80 ether, not {chain.ether['vault']}"
vault.withdraw(savers[0])
assert chain.ether["Ana"] == 20 and chain.ether["vault"] == 60
try:
    vault.withdraw(savers[0])
    raise AssertionError("a second withdrawal must revert")
except Revert:
    pass
for s in savers[1:]:
    vault.withdraw(s)
assert chain.ether["vault"] == 0 and all(chain.ether[s.name] == 20 for s in savers)

